    const M = window.BL.factoryModels, L = M.LAYOUT, G = 0.25, X0 = -21, Z0 = -20, NX = 169, NZ = 201, seen = new Map(), queue = [];
    const add = (i, k, y) => { const key = (i * NZ + k) * 128 + Math.round(y * 4); if (!seen.has(key)) { seen.set(key, [i, k, y]); queue.push(key); } };
